\caption{Equal magnitudes are paired at an earlier and a later phase.
The upper curves depict a nonincreasing weight. In the left panel the
earlier value is $-z$, so the pair contributes
$z\left(w_R-w_L\right)\le0$; in the right panel it is $z$, so the pair contributes
$z\left(w_L-w_R\right)\ge0$. The explicit truncated-pair formulas show why
stopping inside either half-period preserves these signs.}
\label{fig:rounding-pairing}
\end{figure}}

{We first prove the upper bound. If $0\le a\le1/2$, the initial
negative interval is $0<y<a$. If $Y\le a$, then $I\le0$.
Otherwise discard that interval and retain the first positive
half-period, which lies in $a<y<a+1/2$. Its contribution, including
any truncation, is at most}
{\[
 \int_0^{1/2}\frac{1/2-z}{\sqrt{2\kappa\left(a+z\right)}}\,\mathrm{d} z
 \le\int_0^{1/2}\frac{1/2-z}{\sqrt{2\kappa z}}\,\mathrm{d} z
 =\frac1{3\sqrt\kappa}.
\]}
{If $Y>a+1/2$, the remaining tail starts with a negative half-period
and contributes at most zero by
\eqref{eq:rounding-negative-positive} and its truncated form.
The last integral is evaluated by the antiderivative
$2A\sqrt z-\left(2/3\right)z^{3/2}$ of $\left(A-z\right)/\sqrt z$, with $A=1/2$.}

{If $1/2\le a<1$, put $l=a-1/2$. The initial positive values are
$g_a\left(y\right)=l-y$ for $0<y<l$. A stop within this interval retains only
a subset of its positive contribution; a later stop adds a
nonpositive tail of negative--positive pairs. Consequently}
{\[
 I\le\frac1{\sqrt{2\kappa}}
 \left[2l\sqrt y-\frac23 y^{3/2}\right]_0^l
 =\frac{2\sqrt2}{3\sqrt\kappa}l^{3/2}.
\]}
{This proves~\eqref{eq:rounding-phase-upper}. Since $l<1/2$, its
right-hand side is at most $1/\left(3\sqrt\kappa\right)$, completing
the universal upper bound. The argument includes $a=1/2$, when
$l=0$ and the whole integral is a nonpositive paired tail.}

{For the lower bound with $0\le a\le1/2$, the initial negative
values are $g_a\left(y\right)=-\left(1/2-a+y\right)$ on $0<y<a$. A stop in this interval
has loss at most that of the whole interval. After $y=a$, the tail
starts with a positive half-period and is nonnegative by
\eqref{eq:rounding-positive-negative}, including its final truncation.
Using the antiderivative $2A\sqrt y+\left(2/3\right)y^{3/2}$ gives}
{\begin{align*}
 -I&\le\frac1{\sqrt{2\kappa}}
       \int_0^a\frac{1/2-a+y}{\sqrt y}\,\mathrm{d} y\\
 &=\frac1{\sqrt{2\kappa}}
       \left[2\left(1/2-a\right)\sqrt y+\frac23y^{3/2}\right]_0^a
 =\sqrt{\frac{2a}{\kappa}}\left(\frac12-\frac{2a}{3}\right).
\end{align*}}
{This proves~\eqref{eq:rounding-phase-lower}, also at $a=0$ by an
empty initial interval. For $a>0$, differentiation gives}
{\[
 \frac{\mathrm d}{\mathrm d a}
 \left[\sqrt{2a}\left(\frac12-\frac{2a}{3}\right)\right]
 =\frac{\sqrt2}{\sqrt a}\left(\frac14-a\right).
\]}
{The derivative changes sign at $a=1/4$, giving the
maximum $\sqrt2/6$ on $\left[0,1/2\right]$.}

{It remains to bound the loss when $1/2<a<1$. Put $l=a-1/2$ again.
The initial positive value $z$ occurs at $y=l-z$ for $0<z<l$;
its negative match $-z$ occurs at $y=l+z$. If $Y\le l$, then
$I\ge0$. For $l<Y\le a$, write $d=Y-l$. When $d\le l$ the
integral is}
{\[
 \int_0^d z\left[w\left(l-z\right)-w\left(l+z\right)\right]\,\mathrm{d} z
 +\int_d^l z\,w\left(l-z\right)\,\mathrm{d} z\ge0.
\]}
{When $l<d\le1/2$, it is}
{\begin{equation}\label{eq:rounding-initial-positive-pair}
 \int_0^l z\left[w\left(l-z\right)-w\left(l+z\right)\right]\,\mathrm{d} z
 -\int_l^d z\,w\left(l+z\right)\,\mathrm{d} z.
\end{equation}}
{Thus only the negative magnitudes $l<z<d$ can cause a loss. If
$Y>a$, the initial expression is the same with $d=1/2$, and the
tail after the first integer crossing at $y=a$ is a nonnegative
collection of positive--negative pairs. In every case,}
{\[
 I\ge-\int_l^{1/2}\frac{z}{\sqrt{2\kappa\left(l+z\right)}}\,\mathrm{d} z
 \ge-\int_0^{1/2}\sqrt{\frac z{2\kappa}}\,\mathrm{d} z
 =-\frac1{6\sqrt\kappa}
 >-\frac{\sqrt2}{6\sqrt\kappa}.
\]}
{The comparison uses $l+z\ge z$ and enlarges the integration
interval; the antiderivative of $\sqrt z$ is $\left(2/3\right)z^{3/2}$.
This completes both sides of~\eqref{eq:one-sided-rounding}.}

{For sharpness, take an integer $m$ and the quadratic
$q\left(v\right)=m+a-\kappa v^2/2$. Then $w\left(y\right)=1/\sqrt{2\kappa y}$,
so the curvature majorant is an equality. With $a=0$ and
$T=1/\sqrt\kappa$, the integrand equals
$1/2-\kappa v^2/2$ for $0<v<T$, and}
{\[
 \int_0^T\psi\left(q\left(v\right)\right)\,\mathrm{d} v
 =\left[\frac v2-\frac{\kappa v^3}{6}\right]_0^{1/\sqrt\kappa}
 =\frac1{3\sqrt\kappa}.
\]}
{With $a=1/4$ and $T=1/\sqrt{2\kappa}$, it equals
$-1/4-\kappa v^2/2$ except at the endpoint, and}
{\[
 \int_0^T\psi\left(q\left(v\right)\right)\,\mathrm{d} v
 =\left[-\frac v4-\frac{\kappa v^3}{6}\right]_0^{1/\sqrt{2\kappa}}
 =-\frac{\sqrt2}{6\sqrt\kappa}.
\]}
{For every $0<a\le1/2$, stopping the same quadratic at
$T=\sqrt{2a/\kappa}$ attains
\eqref{eq:rounding-phase-lower}. For every $1/2<a<1$, stopping
at $T=\sqrt{2\left(a-1/2\right)/\kappa}$ attains
\eqref{eq:rounding-phase-upper}. The zero endpoint constants are
limits as $T\downarrow0$. The exact examples at $a=0$, $1/4$,
and $3/4$ with $\kappa=1$ are shown in
Figure~\ref{fig:quadratic-sawtooth}.}

\label{lem:all-phase-rounding}
Under the hypotheses of Lemma~\ref{lem:saw}, put
$a=\left\{q\left(0\right)\right\}$. Define on $0\le a\le1$
\[
\begin{aligned}
 C_+\left(a\right)&=
 \begin{cases}
 \displaystyle\int_0^{1/2-a}
       \frac{z}{\sqrt{2\left(1/2+a-z\right)}}\,\mathrm{d} z,
       &0\le a\le1/2,\\[4pt]
 \displaystyle\frac{2\sqrt2}{3}\left(a-1/2\right)^{3/2},
       &1/2\le a\le1,
 \end{cases}\\
 C_-\left(a\right)&=
 \begin{cases}
 \displaystyle\sqrt{2a}\left(\frac12-\frac{2a}{3}\right),
       &0\le a\le1/2,\\[4pt]
 \displaystyle\int_{a-1/2}^{1/2}
       \frac{z}{\sqrt{2\left(a-1/2+z\right)}}\,\mathrm{d} z,
       &1/2\le a\le1.
 \end{cases}
 \end{aligned}
\]
Then
\[
-\frac{C_-\left(a\right)}{\sqrt\kappa}
 \le\int_0^T\psi\left(q\left(v\right)\right)\,\mathrm{d} v
 \le\frac{C_+\left(a\right)}{\sqrt\kappa}.
\]
Both functions are nonnegative and continuous, with matching
endpoint values, and therefore extend continuously with period one.
Their maxima are $1/3$ and $\sqrt2/6$, respectively.
The integral branches have the equivalent expressions
\begin{align}
 C_+\left(a\right)
 &=\frac{\sqrt2}{3}\,
   \frac{\left(1/2-a\right)^2
     \left(2\sqrt{1/2+a}+\sqrt{2a}\right)}
   {\left(\sqrt{1/2+a}+\sqrt{2a}\right)^2},
 &&0\le a\le1/2,\label{eq:rounding-Cplus-rationalized}\\
 C_-\left(a\right)
 &=\frac{\left(1-a\right)\left(1+2\sqrt{a\left(2a-1\right)}\right)}
   {3\sqrt2\left(\sqrt a+\sqrt{2a-1}\right)},
 &&1/2\le a\le1.\label{eq:rounding-Cminus-rationalized}
\end{align}

{First, $q_\delta>0$ for $0<\delta\le5/2$.  Dividing by $A$ gives}
{\[
 {\frac{q_\delta}{A}}=\pi^2-
 \left({\frac{16\left(1+\delta\right)^2}{\left(2+\delta\right)^2}}
       +{\frac{\delta^2}{4\left(1+\delta\right)^2}}\right).
\]}
{Both terms in parentheses increase with $\delta$, and their sum at
$5/2$ is
$784/81+25/196<\left(157/50\right)^2<\pi^2$.
The simpler Cauchy--Schwarz estimate gives}
{\[
 S_\delta\le{\frac{2\pi}{9}}
 \left(2\sqrt h+\sqrt{1-h}\right)^2\le{\frac{10\pi}{9}}<{\frac{7}{2}}
 <X_\delta.
\]}
{Moreover, $z_\delta^*>S_\delta$, so the first branch of
\eqref{eq:Dq-c} is positive.  If $\delta\ge5/2$, then $h\le2/7$
and $b\left(h\right)\le1$.  Since $\sqrt{2/7}<11/20$,}
{\[
 S_\delta<{\frac{2\pi}{9}}\left(1+11/10\right)^2
 ={\frac{49\pi}{50}}<\pi,
\]}
{which proves positivity of the second branch.}

{At every sector Dirichlet eigenvalue, the order is $jp\ge1/2$.
Equation~\eqref{eq:Dq-signed} consequently gives
$\lambda_k\ge\pi^2/\delta^2$.  Thus at $t=\sqrt{\lambda_k}$
one has $x\ge\pi$.}

{Suppose first that $\delta\le5/2$.  When
$\pi\le x\le X_\delta$ only the first radial row contributes to
\eqref{eq:Dq-rows}, apart from a zero-length second row at the last
endpoint.  Completing the square yields}
{\[
 Ax^2-2\sqrt{R^2\left(x^2-\pi^2\right)+\delta^2/4}
 \ge q_\delta.
\]}
{For $\pi\le x\le z_\delta$ it follows that
$B_{\mathrm D}\left(t\right)/t\ge q_\delta/x\ge q_\delta/z_\delta$.
For $x\ge z_\delta$, \eqref{eq:Dq-whole} gives}
{\[
 {\frac{B_{\mathrm D}\left(t\right)}{t}}
 \ge{\frac{R}{2}}\left(1-\sqrt{S_\delta/x}\right)
 \ge{\frac{R}{2}}\left(1-\sqrt{S_\delta/z_\delta}\right).
\]}
{This proves the second entry in the maximum defining $c_\delta$.
The first entry follows directly from \eqref{eq:Dq-whole}, since
$x\ge\pi$.  Hence $B_{\mathrm D}\left(t\right)\ge c_\delta t$ for
every $x\ge\pi$.  The switching point in
\eqref{eq:Dq-qX} maximizes the minimum of these two certificates
over $S_\delta<z\le X_\delta$: the first decreases with $z$,
the second increases, and they agree at $z=z_\delta^*$.
This assertion concerns these two certificates with the completed
square first-row constant $q_\delta$.}

{For $\delta>5/2$, the same conclusion follows directly from
\eqref{eq:Dq-whole}, since $x\ge\pi>S_\delta$.}

{Monotonicity in order and right-endpoint sampling give}
{\[
 pN^{\mathrm D}_S\left(t^2\right)
 \le\int_0^{+\infty}n_v^{\mathrm D}\left(t^2\right)\,\mathrm{d} v
 ={\frac{1}{2}}M_{\mathrm D}\left(t\right).
\]}
{Taking $t^2=\lambda_k$ and using $N^{\mathrm D}_S\left(\lambda_k\right)\ge k$
therefore yields, for normalized radii,}
{\[
 \lambda_k-W_k\ge{\frac{4}{D}}B_{\mathrm D}\left(\sqrt{\lambda_k}\right)
 \ge{\frac{4c_\delta}{D}}\sqrt{\lambda_k}.
\]}
{For $x\ge\pi$ the same sampling argument yields
$N^{\mathrm D}_S\left(t^2\right)\le D\left(t^2-4c_\delta t/D\right)/\left(8p\right)$.
For $x<\pi$ the sector count is zero, by
\eqref{eq:Dq-signed} and $jp\ge1/2$.  Taking the positive part
therefore gives \eqref{eq:Dq-all-count} at every energy after scaling.
Solving the quadratic inequality for $\sqrt{\lambda_k}$ and
scaling lengths by $r$ proves \eqref{eq:Dq-all-eigen}.}

\label{thm:Dq-certificate-inverse}
For $k\ge1$, put
\begin{equation}\label{eq:Dq-sigma}
 \sigma_k\left(\delta,p\right)
 =\sup\left\{t>0:U_{\delta,p}\left(t\right)<k\right\}.
\end{equation}
This supremum is positive and finite.  For an annular sector with
physical radii $r<R_0$, set
$\delta=R_0/r-1$ and $p=\pi/\beta$.  Then
\begin{equation}\label{eq:Dq-sigma-eigen}
 \lambda_k\left(S_{r,R_0,\beta}\right)
 \ge{\frac{\sigma_k\left(\delta,p\right)^2}{r^2}}.
\end{equation}
In normalized variables, with $w_k=\sqrt{8pk/D}$, one also has
\begin{equation}\label{eq:Dq-sigma-explicit}
 \sigma_k\left(\delta,p\right)\ge
 \max\left\{
   \sqrt{w_k^2+\frac{4c_\delta^2}{D^2}}+\frac{2c_\delta}D,
   \sqrt{\frac{\pi^2}{\delta^2}+\frac{p^2-1/4}{R^2}}\right\}.
\end{equation}
In particular, \eqref{eq:Dq-sigma-eigen} retains the positive
all-index correction \eqref{eq:Dq-all-eigen}.
An explicit upper search endpoint is
\begin{equation}\label{eq:Dq-sigma-search-endpoint}
 \sigma_k\left(\delta,p\right)
 \le\sqrt{\frac{\pi^2}{\delta^2}+k^2p^2-\frac14}.
\end{equation}
For fixed $\delta,p$, its asymptotic correction is
\begin{equation}\label{eq:Dq-sigma-asymptotic}
 \sigma_k\left(\delta,p\right)^2-w_k^2
 ={\frac{4L_\delta}{D}}w_k+o_{\delta,p}\left(w_k\right),
 \qquad k\longrightarrow+\infty,
 \qquad L_\delta=\frac{R+1}2.
\end{equation}

{The loss tends to infinity as $u\uparrow1$, and}
{\[
 \begin{aligned}
\partial_uJ\left(t,u\right)&=2I'\left(u\right)-t\left(1+2c\left(ut\right)\right),\\
 I'\left(u\right)&=\frac{9-2u^2}{24\pi\left(1-u^2\right)^{3/2}},\\
 I''\left(u\right)&=\frac{u\left(23-2u^2\right)}{24\pi\left(1-u^2\right)^{5/2}}.
\end{aligned}
\]}
{Thus $I'$ is strictly increasing on $\left[0,1\right)$, while $c\left(ut\right)$ is
nonincreasing.  The derivative of $J$ is strictly increasing,
starts at $3/\left(4\pi\right)-q_0t$, and tends to infinity.  This proves
all claims about the minimizer.  Continuity follows from the
strict root characterization, including the root tending to zero
as $t\downarrow t_c$.}

\label{prop:Nq-count}
For every $\delta>0$ and $t>0$,
\begin{equation}\label{eq:Nq-count}
 M\left(t\right)>\frac D4t^2+tB_\delta\left(t\right),\qquad B_\delta\left(t\right)>0.
\end{equation}
The envelope is continuous and satisfies
$B_\delta\left(t\right)\to\left(R+1\right)/2$ as $t\to+\infty$.

{Strict angular transfer and continuity of $M$ give}
{\[
 N_S^<\left(E\right)\ge\frac{M\left(r\sqrt E\right)}{2p}
 >\frac{\left|S\right|}{4\pi}E+
            \frac{rb_\delta^{\rm c}}{2p}\sqrt E.
\]}
{At $E=\left(\tau_k^{\rm c}/r\right)^2$ the last expression is $k$,
because $\left(\tau_k^{\rm c}\right)^2+2A_\delta\tau_k^{\rm c}=w_k^2$.
The integer count is therefore at least $k+1$, including the
zero mode.  Thus $\mu_k\left(S\right)<E$, and subtraction from $W_k$
gives \eqref{eq:Nq-all-gap}.}

\label{lem:Bq-discrete-averaging}
Fix $R>1$, $p>0$, and a compact interval $I$ contained in $\left(0,1\right)$
or $\left(1,R\right)$.  For every nonzero integer $h$,
\begin{equation}\label{eq:Bq-exponential-sum}
 \sum_{pj/t\in I}\exp\left(2\pi\mathrm i h f_t\left(pj\right)\right)
       =O_{R,p,I,h}\left(\sqrt t\right).
\end{equation}
Consequently, for every bounded Riemann integrable function $H$
of period one and every constant $c$,
\begin{equation}\label{eq:Bq-discrete-mean}
 \frac1t\sum_{pj/t\in I}H\left(f_t\left(pj\right)+c\right)
       \longrightarrow\frac{\left|I\right|}p\int_0^1H\left(y\right)\,\mathrm{d} y.
\end{equation}

{Write the eigenvalues of $\Omega$ as $\nu_\ell$, $\ell\ge0$,
with $\nu_0=0$, and put $N_S^{<}\left(z\right)=0$ for $z\le0$.
The tensor products of the two factor eigenbases are a complete
orthonormal eigenbasis for the product form, with eigenvalues
$\mu_j\left(S\right)+\nu_\ell$. The compactness of the form embeddings
on the factors gives a discrete product spectrum; for a slit sector
the same statement holds on its polar rectangle. Product separation
and Theorem~\ref{thm:main} therefore give, for $E>0$,}
{\[
\begin{aligned}
 N_{S\times\Omega}^{<}\left(E\right)
 &=\sum_{\ell\ge0}N_S^{<}\left(E-\nu_\ell\right)\\
 &>\frac{\left|S\right|}{4\pi}
             \sum_{\ell\ge0}\left(E-\nu_\ell\right)_{+}.
\end{aligned}
\]}
{Only finitely many summands are nonzero. The inequality remains
strict because the summand $\ell=0$ has positive argument $E$.}

{For clarity, we give the sharp lower bound on the Riesz mean of
the other factor; it is the plane-wave argument underlying the
Neumann spectral-sum estimates~\cite{Kroger,Laptev}. Let
$\phi_\ell$ be an orthonormal Neumann eigenbasis of $L^2\left(\Omega\right)$,
and define $e_\xi\left(y\right)=\left(2\pi\right)^{-d/2}e^{i\xi\cdot y}$
on $\Omega$. This function belongs to the Neumann form domain.
Its spectral expansion satisfies}
{\[
\begin{aligned}
 \sum_{\ell\ge0}\left|\left\langle e_\xi,\phi_\ell\right\rangle\right|^2
 &=\left(2\pi\right)^{-d}\left|\Omega\right|,\\
 \sum_{\ell\ge0}\nu_\ell
          \left|\left\langle e_\xi,\phi_\ell\right\rangle\right|^2
 &=\int_\Omega\left|\nabla e_\xi\right|^2\,\mathrm{d} y
 =\left(2\pi\right)^{-d}\left|\Omega\right|\left|\xi\right|^2.
\end{aligned}
\]}
{Replacing $E-\nu_\ell$ by its positive part increases the sum, so}
{\[
 \sum_{\ell\ge0}\left(E-\nu_\ell\right)_{+}
       \left|\left\langle e_\xi,\phi_\ell\right\rangle\right|^2
 \ge\left(2\pi\right)^{-d}\left|\Omega\right|\left(E-\left|\xi\right|^2\right).
\]}
{Integrate over $\left|\xi\right|<\sqrt E$. Plancherel's theorem applied
to the zero extension of $\phi_\ell$ gives}
{\[
 \int_{\left|\xi\right|<\sqrt E}
       \left|\left\langle e_\xi,\phi_\ell\right\rangle\right|^2\,\mathrm{d}\xi
 \le\int_{\mathbb R^d}\left|\left\langle e_\xi,\phi_\ell\right\rangle\right|^2\,\mathrm{d}\xi=1.
\]}
It follows that
{\[
\begin{aligned}
 \sum_{\ell\ge0}\left(E-\nu_\ell\right)_{+}
 &\ge\frac{\left|\Omega\right|}{\left(2\pi\right)^d}
            \int_{\left|\xi\right|<\sqrt E}\left(E-\left|\xi\right|^2\right)\,\mathrm{d}\xi\\
 &=\frac{\left|\Omega\right|}{\left(2\pi\right)^d}
        d\omega_d\int_0^{\sqrt E}\left(E-\rho^2\right)\rho^{d-1}\,\mathrm{d}\rho\\
 &=\frac{2\omega_d\left|\Omega\right|}{\left(d+2\right)\left(2\pi\right)^d}
                                   E^{\left(d+2\right)/2}.
\end{aligned}
\]}
{Since $\omega_{d+2}=2\pi\omega_d/\left(d+2\right)$, we conclude that}
{\[
 N_{S\times\Omega}^{<}\left(E\right)
 >\frac{\omega_{d+2}\left|S\right|\left|\Omega\right|}{\left(2\pi\right)^{d+2}}
                                  E^{\left(d+2\right)/2}.
\]}
{Taking the right-hand side equal to $k$ proves the eigenvalue bound
with the same indexing argument as in Theorem~\ref{thm:main}.}
